const fs = require('fs');
const { chromium } = require('playwright');
(async () => {
  const png = fs.readFileSync('/app/output/final_poster.png');
  const width = png.readUInt32BE(16);
  const height = png.readUInt32BE(20);
  console.log(`png ${width}x${height}, ${png.length} bytes`);

  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage({ viewport: { width: 1800, height: 2700 }, deviceScaleFactor: 1 });
  await page.goto('file:///app/output/hunger_poster.html', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts && document.fonts.ready);
  const issues = await page.evaluate(() => {
    const poster = document.querySelector('.poster').getBoundingClientRect();
    const selectors = ['h1', '.lead', '.stat-panel', '.evidence-item', '.conversion', '.action'];
    const out = [];
    for (const selector of selectors) {
      document.querySelectorAll(selector).forEach((el, i) => {
        const r = el.getBoundingClientRect();
        if (r.left < poster.left - 1 || r.top < poster.top - 1 || r.right > poster.right + 1 || r.bottom > poster.bottom + 1) {
          out.push(`${selector}[${i}] outside poster bounds`);
        }
        if (el.scrollWidth > el.clientWidth + 2 || el.scrollHeight > el.clientHeight + 2) {
          out.push(`${selector}[${i}] scroll overflow ${el.scrollWidth}x${el.scrollHeight} > ${el.clientWidth}x${el.clientHeight}`);
        }
      });
    }
    return out;
  });
  console.log(issues.length ? issues.join('\n') : 'layout checks passed');
  await browser.close();
})();
